export const DEFAULT_THEME = new Theme();
function anchorsEqual(a, b) {
    if (a === b)
        return true;
    if (!a || !b)
        return false;
    return a.owner === b.owner && a.row === b.row && a.col === b.col && anchorsEqual(a.inner, b.inner);
}
