/** Sprig math utilities — int and float arithmetic. */

import type { FuncMap } from "../../evaluator/evaluator.js";
import { add } from "./add.js";
import { add1 } from "./add1.js";
import { add1f } from "./add1f.js";
import { addf } from "./addf.js";
import { ceil } from "./ceil.js";
import { div } from "./div.js";
import { divf } from "./divf.js";
import { floor } from "./floor.js";
import { max } from "./max.js";
import { maxf } from "./maxf.js";
import { min } from "./min.js";
import { minf } from "./minf.js";
import { mod } from "./mod.js";
import { mul } from "./mul.js";
import { mulf } from "./mulf.js";
import { round } from "./round.js";
import { seq } from "./seq.js";
import { sub } from "./sub.js";
import { subf } from "./subf.js";
import { until } from "./until.js";
import { untilStep } from "./untilStep.js";

export {
  add,
  add1,
  add1f,
  addf,
  ceil,
  div,
  divf,
  floor,
  max,
  maxf,
  min,
  minf,
  mod,
  mul,
  mulf,
  round,
  seq,
  sub,
  subf,
  until,
  untilStep,
};

export function sprigMath(): FuncMap {
  // [LAW:single-enforcer] enforceArgTypes normalizes numeric slots to
  // plain `number` before dispatch. Sprig reads its `interface{}` math
  // arguments through `cast.ToInt64`, so those slots are
  // "truncating-int" (`max 1.5 2.5` is 2); `seq`/`until`/`untilStep` and
  // `round`'s precision are Go `int` parameters, so they are "int" and
  // refuse a fractional. "float" arrives coerced (IEEE-754 semantics).
  // Bodies receive `number`, never `bigint`.
  return {
    add: {
      fn: (...a) => add(...(a as number[])),
      argTypes: ["truncating-int"],
      arity: { kind: "variadic" },
    },
    sub: {
      fn: (a, b) => sub(a as number, b as number),
      argTypes: ["truncating-int", "truncating-int"],
      arity: { kind: "exact" },
    },
    mul: {
      fn: (...a) => mul(...(a as number[])),
      argTypes: ["truncating-int", "truncating-int"],
      arity: { kind: "variadic" },
    },
    div: {
      fn: (a, b) => div(a as number, b as number),
      argTypes: ["truncating-int", "truncating-int"],
      arity: { kind: "exact" },
    },
    mod: {
      fn: (a, b) => mod(a as number, b as number),
      argTypes: ["truncating-int", "truncating-int"],
      arity: { kind: "exact" },
    },
    min: {
      fn: (...a) => min(...(a as number[])),
      argTypes: ["truncating-int", "truncating-int"],
      arity: { kind: "variadic" },
    },
    max: {
      fn: (...a) => max(...(a as number[])),
      argTypes: ["truncating-int", "truncating-int"],
      arity: { kind: "variadic" },
    },
    floor: { fn: (a) => floor(a as number), argTypes: ["float"], arity: { kind: "exact" } },
    ceil: { fn: (a) => ceil(a as number), argTypes: ["float"], arity: { kind: "exact" } },
    // Go: `round(a interface{}, p int, rOpt ...float64)` — the
    // precision is a *required* parameter and only the rounding
    // threshold is variadic, so Go rejects `round 3.7`. `arity`
    // declares that gate; the body's `precision = 0` default and its
    // silent drop of `rOpt` are body-side gaps tracked on the
    // conformance epic, not reasons to widen the declaration.
    round: {
      fn: (a, p) => round(a as number, p as number),
      argTypes: ["float", "int", "float"],
      arity: { kind: "variadic" },
    },
    addf: {
      fn: (...a) => addf(...(a as number[])),
      argTypes: ["float"],
      arity: { kind: "variadic" },
    },
    // Go: `subf(a interface{}, v ...interface{})` — folds over every
    // argument, unlike the integer `sub`, which Go declares with two
    // fixed parameters.
    subf: {
      fn: (a, ...rest) => subf(a as number, ...(rest as number[])),
      argTypes: ["float", "float"],
      arity: { kind: "variadic" },
    },
    mulf: {
      fn: (...a) => mulf(...(a as number[])),
      argTypes: ["float", "float"],
      arity: { kind: "variadic" },
    },
    // Go: `divf(a interface{}, v ...interface{})` — folds over every
    // argument, unlike the integer `div`.
    divf: {
      fn: (a, ...rest) => divf(a as number, ...(rest as number[])),
      argTypes: ["float", "float"],
      arity: { kind: "variadic" },
    },
    add1: { fn: (n) => add1(n as number), argTypes: ["truncating-int"], arity: { kind: "exact" } },
    add1f: { fn: (n) => add1f(n as number), argTypes: ["float"], arity: { kind: "exact" } },
    maxf: {
      fn: (...a) => maxf(...(a as number[])),
      argTypes: ["float", "float"],
      arity: { kind: "variadic" },
    },
    minf: {
      fn: (...a) => minf(...(a as number[])),
      argTypes: ["float", "float"],
      arity: { kind: "variadic" },
    },
    // `biggest` is Go sprig's deprecated alias for `max`. Registered
    // directly against the same function so divergence is impossible.
    biggest: {
      fn: (...a) => max(...(a as number[])),
      argTypes: ["truncating-int", "truncating-int"],
      arity: { kind: "variadic" },
    },
    seq: {
      fn: (...a) => seq(...(a as number[])),
      argTypes: ["int"],
      arity: { kind: "variadic" },
      returnType: "string",
    },
    until: {
      fn: (n) => until(n as number),
      argTypes: ["int"],
      arity: { kind: "exact" },
      returnType: "list",
    },
    untilStep: {
      fn: (a, b, c) => untilStep(a as number, b as number, c as number),
      argTypes: ["int", "int", "int"],
      arity: { kind: "exact" },
      returnType: "list",
    },
  };
}
