/**
 * Sprig string utilities.
 *
 * Each function lives in its own file with a co-located unit test.
 * `sprigStrings()` bundles them as a FuncMap for one-line consumer
 * registration on the engine.
 */

import type { FuncMap } from "../../evaluator/evaluator.js";
import { abbrev } from "./abbrev.js";
import { abbrevboth } from "./abbrevboth.js";
import { camelcase } from "./camelcase.js";
import { cat } from "./cat.js";
import { contains } from "./contains.js";
import { hasPrefix } from "./hasPrefix.js";
import { hasSuffix } from "./hasSuffix.js";
import { indent } from "./indent.js";
import { initials } from "./initials.js";
import { join } from "./join.js";
import { kebabcase } from "./kebabcase.js";
import { lower } from "./lower.js";
import { nindent } from "./nindent.js";
import { nospace } from "./nospace.js";
import { plural } from "./plural.js";
import { quote } from "./quote.js";
import { regexQuoteMeta } from "./regexQuoteMeta.js";
import { repeat } from "./repeat.js";
import { replace } from "./replace.js";
import { snakecase } from "./snakecase.js";
import { split } from "./split.js";
import { splitList } from "./splitList.js";
import { splitn } from "./splitn.js";
import { squote } from "./squote.js";
import { substr } from "./substr.js";
import { swapcase } from "./swapcase.js";
import { title } from "./title.js";
import { trim } from "./trim.js";
import { trimAll } from "./trimAll.js";
import { trimPrefix } from "./trimPrefix.js";
import { trimSuffix } from "./trimSuffix.js";
import { trunc } from "./trunc.js";
import { untitle } from "./untitle.js";
import { upper } from "./upper.js";
import { wrap } from "./wrap.js";
import { wrapWith } from "./wrapWith.js";

export {
  abbrev,
  abbrevboth,
  camelcase,
  cat,
  contains,
  hasPrefix,
  hasSuffix,
  indent,
  initials,
  join,
  kebabcase,
  lower,
  nindent,
  nospace,
  plural,
  quote,
  regexQuoteMeta,
  repeat,
  replace,
  snakecase,
  split,
  splitList,
  splitn,
  squote,
  substr,
  swapcase,
  title,
  trim,
  trimAll,
  trimPrefix,
  trimSuffix,
  trunc,
  untitle,
  upper,
  wrap,
  wrapWith,
};

export function sprigStrings(): FuncMap {
  // [LAW:single-enforcer] argTypes is the contract describing what each
  // func accepts; enforceArgTypes runs at the boundary, so the `as`
  // casts below are provably-safe — the runtime types match the
  // declared argTypes. Numeric slots use "int" (Go declares every one
  // of them `int`): the gate accepts integer-valued `number` and
  // safe-integer `bigint` (|n| ≤ 2^53), normalizes both to a `number`,
  // and rejects fractionals, out-of-range bigints, NaN, and ±Infinity
  // at the boundary. Bodies receive plain `number` and
  // drop the body-side `Number(v)` coercions that used to re-do the
  // gate's work. See template-variance-num-carrier-hfv.3.
  return {
    abbrev: {
      fn: (w, s) => abbrev(w as number, s as string),
      argTypes: ["int", "string"],
      arity: { kind: "exact" },
    },
    abbrevboth: {
      fn: (l, r, s) => abbrevboth(l as number, r as number, s as string),
      argTypes: ["int", "int", "string"],
      arity: { kind: "exact" },
    },
    camelcase: {
      fn: (s) => camelcase(s as string),
      argTypes: ["string"],
      arity: { kind: "exact" },
      returnType: "string",
    },
    cat: {
      fn: (...a) => cat(...(a as string[])),
      argTypes: ["string"],
      arity: { kind: "variadic" },
    },
    contains: {
      fn: (sub, s) => contains(sub as string, s as string),
      argTypes: ["string", "string"],
      arity: { kind: "exact" },
    },
    hasPrefix: {
      fn: (p, s) => hasPrefix(p as string, s as string),
      argTypes: ["string", "string"],
      arity: { kind: "exact" },
    },
    hasSuffix: {
      fn: (sf, s) => hasSuffix(sf as string, s as string),
      argTypes: ["string", "string"],
      arity: { kind: "exact" },
    },
    indent: {
      fn: (n, s) => indent(n as number, s as string),
      argTypes: ["int", "string"],
      arity: { kind: "exact" },
    },
    initials: { fn: (s) => initials(s as string), argTypes: ["string"], arity: { kind: "exact" } },
    join: {
      fn: (sep, list) => join(sep as string, list as unknown[]),
      argTypes: ["string", "list"],
      arity: { kind: "exact" },
    },
    kebabcase: {
      fn: (s) => kebabcase(s as string),
      argTypes: ["string"],
      arity: { kind: "exact" },
      returnType: "string",
    },
    lower: { fn: (s) => lower(s as string), argTypes: ["string"], arity: { kind: "exact" } },
    nindent: {
      fn: (n, s) => nindent(n as number, s as string),
      argTypes: ["int", "string"],
      arity: { kind: "exact" },
    },
    nospace: {
      fn: (s) => nospace(s as string),
      argTypes: ["string"],
      arity: { kind: "exact" },
      returnType: "string",
    },
    plural: {
      fn: (one, many, n) => plural(one as string, many as string, n as number),
      argTypes: ["string", "string", "int"],
      arity: { kind: "exact" },
      returnType: "string",
    },
    quote: {
      fn: (...a) => quote(...(a as string[])),
      argTypes: ["string"],
      arity: { kind: "variadic" },
    },
    regexQuoteMeta: {
      fn: (s) => regexQuoteMeta(s as string),
      argTypes: ["string"],
      arity: { kind: "exact" },
      returnType: "string",
    },
    repeat: {
      fn: (n, s) => repeat(n as number, s as string),
      argTypes: ["int", "string"],
      arity: { kind: "exact" },
    },
    replace: {
      fn: (o, n, s) => replace(o as string, n as string, s as string),
      argTypes: ["string", "string", "string"],
      arity: { kind: "exact" },
    },
    snakecase: {
      fn: (s) => snakecase(s as string),
      argTypes: ["string"],
      arity: { kind: "exact" },
      returnType: "string",
    },
    split: {
      fn: (sep, s) => split(sep as string, s as string),
      argTypes: ["string", "string"],
      arity: { kind: "exact" },
    },
    splitList: {
      fn: (sep, s) => splitList(sep as string, s as string),
      argTypes: ["string", "string"],
      arity: { kind: "exact" },
    },
    splitn: {
      fn: (sep, n, s) => splitn(sep as string, n as number, s as string),
      argTypes: ["string", "int", "string"],
      arity: { kind: "exact" },
      returnType: "dict",
    },
    squote: {
      fn: (...a) => squote(...(a as string[])),
      argTypes: ["string"],
      arity: { kind: "variadic" },
    },
    substr: {
      fn: (i, j, s) => substr(i as number, j as number, s as string),
      argTypes: ["int", "int", "string"],
      arity: { kind: "exact" },
    },
    swapcase: {
      fn: (s) => swapcase(s as string),
      argTypes: ["string"],
      arity: { kind: "exact" },
      returnType: "string",
    },
    title: { fn: (s) => title(s as string), argTypes: ["string"], arity: { kind: "exact" } },
    trim: { fn: (s) => trim(s as string), argTypes: ["string"], arity: { kind: "exact" } },
    trimAll: {
      fn: (cs, s) => trimAll(cs as string, s as string),
      argTypes: ["string", "string"],
      arity: { kind: "exact" },
    },
    trimPrefix: {
      fn: (p, s) => trimPrefix(p as string, s as string),
      argTypes: ["string", "string"],
      arity: { kind: "exact" },
    },
    trimSuffix: {
      fn: (sf, s) => trimSuffix(sf as string, s as string),
      argTypes: ["string", "string"],
      arity: { kind: "exact" },
    },
    trunc: {
      fn: (n, s) => trunc(n as number, s as string),
      argTypes: ["int", "string"],
      arity: { kind: "exact" },
    },
    untitle: { fn: (s) => untitle(s as string), argTypes: ["string"], arity: { kind: "exact" } },
    upper: { fn: (s) => upper(s as string), argTypes: ["string"], arity: { kind: "exact" } },
    wrap: {
      fn: (w, s) => wrap(w as number, s as string),
      argTypes: ["int", "string"],
      arity: { kind: "exact" },
    },
    wrapWith: {
      fn: (w, sep, s) => wrapWith(w as number, sep as string, s as string),
      argTypes: ["int", "string", "string"],
      arity: { kind: "exact" },
    },
  };
}
