// [LAW:one-source-of-truth] brandon-layout-edit-2gc.3's CHROME half — the
// LOWERING that turns "edit mode is a session toggle" into "each row's
// segments render interleaved with +/- affordances" without a render-walk
// branch [LAW:dataflow-not-control-flow]. Follows the SAME move `kind:
// "group"` sugar makes (src/config/loader/layout.ts): one pass produces a NEW
// tree with synthesized nodes spliced in, each gated by an ordinary `when` —
// the walk that renders it learns nothing new. The difference from group
// sugar is WHEN this can run: a group is authored data, lowered per file
// before merge; edit chrome is DERIVED from which segments are actually in
// the tree, which is only known after merge and preset-root resolution. So
// this runs from validateRenderable, on the fully resolved
// config each declared preset stages — see synthesizeEditChrome below.
//
// [LAW:single-enforcer] The +/- affordances reuse EXISTING primitives
// wholesale rather than inventing parallel ones: `-` is an ordinary
// `{ persist, removeSegment }` action behind `{{ action }}` (2gc.1); `+` is an
// ordinary `{ persist, insertSegmentFrom }` action behind `{{ menu }}`
// (2gc.3's new arm — see action.ts), synthesized by calling the SAME pure
// functions `{{ menu }}`'s own load-time synthesis calls
// (menu-keys.ts/disclosure.ts) so a synthesized menu and a hand-authored one
// are indistinguishable at render. Nothing here is a new render concept.

import path from "node:path";
import { synthesisInputs } from "./synthesis-inputs.js";
import type { ActionDecl as ActionDeclType } from "./action.js";
import {
  mapOpens,
  placementId,
  settingSpelling,
  settingsOf,
  IMPLIED_SETTINGS,
  walkNodes,
  type ContainerNode,
  type DisclosureRef,
  type DslConfig,
  type InsertedBy,
  type LayoutNode,
  type PresetDecl,
  type SegmentDecl,
  type SegmentNode,
  type DraftSlot,
  type SettingDecl,
  type VariableDecl,
} from "./dsl-types.js";
import { presetByName, presetNames, presetRoot } from "./presets.js";
import { perConfigDomainsFor, type ResolvedDomain } from "./option-domain.js";
import { controlDeclOf, settingControl } from "./setting-control.js";
import { presetRootKey } from "./loader/persist-target.js";
import { ident } from "./ident.js";
import { GROUP_LABELS, LIBRARY_GROUPS, OTHER_GROUP } from "./segment-groups.js";
import {
  configureMember,
  EDIT_MODE_GATE,
  EDIT_CONFIGURE_KEY,
  EDIT_MODE_REF,
  EDIT_TOGGLE_ACTION,
  PLACEMENT_DRAFT_NS,
} from "./loader/edit-mode.js";
import { EDIT_NS, isReservedName } from "./loader/reserved-namespace.js";
import { declareHelp } from "./help.js";
import { TEXT_MIN_CONTRAST } from "../themes/decor.js";
import { NO_FILL } from "../template-engine/colors.js";
import { EDIT_MODE_HELP } from "../help-text.js";
import { ADD_GLYPH, CONFIGURE_GLYPH, REMOVE_GLYPH } from "./edit-glyphs.js";
import { SAVE_SEG, UNSAVED_VAR } from "./settings-menu.js";
import {
  menuActionName,
  menuMember,
  menuPageKey,
  sharedMenuStateKey,
  menuStateKey,
} from "./menu-keys.js";
import {
  DISCLOSURE_CLOSED,
  DISCLOSURE_GLYPH_CLOSE,
  escapeTemplateLiteral,
  disclosureCycleAction,
  disclosureNode,
  disclosureStateVar,
  disclosureTerm,
  disclosureTrigger,
} from "./disclosure.js";

// [LAW:one-source-of-truth] Edit mode shows the ARRANGEMENT: every content
// cell reads as its segment's name, so a segment whose own `when` hides it
// (no ssh session, an idle cache timer) is still there to move or remove —
// its `-` would otherwise sit beside nothing. `☐ live` swaps the names back
// for the live output. It is a binary toggle over one SessionState key, which
// is what a disclosure ref already names, so both gates below derive from the
// one term spelling rather than a second `eq`.
export const EDIT_LIVE_KEY = `${EDIT_NS}live`;
// The toggle's text per state, names view (closed) first.
export const EDIT_LIVE_DISPLAY = ["☐ live", "☑ live"] as const;
// Leaving edit mode, kept: `✓ save` while there is something to keep, `✓ done`
// while there is not. The two are one action: write the session's unsaved
// settings (a placement's configure-mode picks among them — the layout edits
// were written as they were made), then leave.
export const EDIT_DONE_SEG = `${EDIT_NS}done`;
// `↩ cancel`: put back everything changed since edit mode opened, then leave
// (src/daemon/settings-history.ts `rewind`).
export const EDIT_CANCEL_SEG = `${EDIT_NS}cancel`;
const EDIT_REWIND_ACTION = `${EDIT_NS}rewind`;
// How many targets differ from when edit mode opened (HistoryDepth.sinceEdit)
// — the daemon's own count, read by the cells' labels and gates; a ref, never
// a second counter. How many settings are unsaved is the settings menu's own
// `unsaved` variable.
const EDIT_CHANGES_VAR = `${EDIT_NS}changes`;
const CHANGED = `(gt .${EDIT_CHANGES_VAR} 0)`;
const TO_KEEP = `(or ${CHANGED} (gt .${UNSAVED_VAR} 0))`;
const EDIT_LIVE_REF: DisclosureRef = {
  variable: EDIT_LIVE_KEY,
  key: EDIT_LIVE_KEY,
  member: "open",
};
// Configuring a placement shows the live output too: its settings change what
// it draws, and a name cannot show that.
//
// [LAW:one-source-of-truth] "A placement is configured" is a fact about the
// tree this preset renders, not about the key alone: the key can name a
// placement this tree does not hold — one a layout edit removed, or one in
// another preset — and then nothing is configured here and the names view
// stands. So the fact is a per-preset template variable over exactly the
// members this preset's configure bodies open on, minted once its splice has
// collected them (configuringVar); every gate reads it.
function configuringVar(presetIdent: string): string {
  return `${EDIT_NS}configuring.p${presetIdent}`;
}
function namesView(presetIdent: string): string {
  return `and ${disclosureTerm(EDIT_MODE_REF)} (not ${disclosureTerm(EDIT_LIVE_REF)}) (ne .${configuringVar(presetIdent)} "true")`;
}
function configuringDecl(members: readonly string[]): VariableDecl {
  const terms = members.map(
    (m) => `(eq .${EDIT_CONFIGURE_KEY} "${escapeTemplateLiteral(m)}")`,
  );
  return { kind: "template", template: `{{ or ${terms.join(" ")} false }}` };
}

// [LAW:dataflow-not-control-flow] The names view decides a gate outright;
// every other view hands it to the author's own `when`, evaluated exactly as
// it was. A `when` is a whole template body, so it nests verbatim in the
// `else` arm — no second node is needed to conjoin two predicates. A content
// cell holds its label AND its live segment, always: in the names view the
// segment is `false` and the label shows, and an authored container is `true`
// so nothing placed hides behind a gate; outside it the label is false and
// the bar renders exactly what it renders without edit mode.
function inNamesView(
  presetIdent: string,
  verdict: "true" | "false",
  when: string,
): string {
  return `{{ if ${namesView(presetIdent)} }}${verdict}{{ else }}${when}{{ end }}`;
}

// [LAW:dataflow-not-control-flow] brandon-layout-edit-2gc.5's diagnostic gate.
// `.preset.customized` is a per-render payload fact (does the config FILE
// author a root for whichever preset is ACTIVE — entry.state.authoredRoots),
// not config-time knowledge, so the banner below is spliced UNCONDITIONALLY
// for every preset — same shape, every reload — and this predicate is what
// decides whether it's visible, never a branch in this synthesis pass.
//
// [LAW:one-type-per-behavior] The banner is an edit affordance of the same
// class as `-`/`+` — one click rewrites the file's root — so it shows under
// the same condition they do (edit mode open) AND only when it has something
// to reset. Under candybar-config-dqe "customized" means "the file authors a
// root", the ordinary state of every hand-written config; a banner gated on
// that alone would sit permanently on such bars, outside edit mode, as a
// one-click deletion of the author's own layout. The edit-mode term is
// disclosureTerm over the SAME ref every other chrome gate derives from; the
// customized term is the bare boolean input var, false only on the literal
// text "false" (evaluateWhen's documented contract), and `and` yields the
// last argument when every term is truthy — so the conjunction reads back
// exactly as the boolean does.
// [LAW:one-source-of-truth] Exported: test/helpers/ambient-chrome.ts filters this
// ensured name out of "what did the AUTHOR declare" assertions and must read the
// same string, never a second copy that a rename here would leave behind.
export const PRESET_CUSTOMIZED_VAR = "preset.customized";
const CUSTOMIZED_BANNER_GATE = `{{ and ${disclosureTerm(EDIT_MODE_REF)} .${PRESET_CUSTOMIZED_VAR} }}`;

// [LAW:one-source-of-truth] Every synthesized segment is structural — removing
// one via `-` would strand its sibling artifacts (a toggle segment with no
// body, a menu with no host), and offering one back via `+` would insert a
// bare ref with none of the synthesis that made it work; the settings menu is
// also the door edit mode is REACHED from, so a `-` beside it would be a
// self-lockout. Ordinary content segments only.
const isChromeExempt = isReservedName;

// [LAW:one-source-of-truth] Every synthesized decl this pass produces, keyed
// by its final name — one accumulator threaded through every preset's splice
// so cross-preset names (disambiguated by `presetIdent`) can never collide.
interface ChromeArtifacts {
  readonly variables: Record<string, VariableDecl>;
  readonly actions: Record<string, ActionDeclType>;
  readonly segments: Record<string, SegmentDecl>;
}

// [LAW:one-source-of-truth] The domain name every `+` picker ranges, consumed
// two ways: here (by name, for every insertSegmentFrom action the splice
// synthesizes) and by `configOptionDomains`, which every resolution of a
// `from` reads. Both read this one string, so a synthesized action's domain
// name always resolves.

// [LAW:one-source-of-truth] Every option domain a config's actions may name
// beyond the global registry: its styles and presets, and the addable
// segments. The loader's refusal of an unknown name, the render's options,
// and both click gates resolve against this one map, so a name the render
// draws options from is never one the loader refuses or a gate cannot find.
export function configOptionDomains(
  config: Pick<DslConfig, "styles" | "presets" | "segments">,
): ReadonlyMap<string, ResolvedDomain> {
  return new Map([
    ...perConfigDomainsFor(config),
    ...addableSegmentDomains(config),
  ]);
}
export const ADDABLE_DOMAIN = `${EDIT_NS}addable`;

// [LAW:one-source-of-truth] THE "what can `+` offer" set: every declared,
// non-exempt segment name. A segment already on the bar is offered too — a
// placement is an instance (brandon-segment-settings-i4n), so a second one is
// a second instance with its own id and its own settings, minted when the
// click lands (`mintPlacement`, layout-ops.ts). It joins the config's other
// domains in `configOptionDomains`.
export function addableSegmentDomains(
  config: Pick<DslConfig, "segments">,
): ReadonlyMap<string, ResolvedDomain> {
  // Segment names carry no colour, so this domain declares no `paletteOf` —
  // a `+` picker's options keep their band placement. What it DOES know about
  // itself is that its members are a catalogue: each segment's authored `group`
  // and `description` (absent group: `other`), so the picker lays it out as a
  // library. [LAW:one-source-of-truth] Read from the declarations themselves,
  // so a segment from any config — a user's, a future bundled one — is in the
  // library with no wiring.
  return new Map([
    [
      ADDABLE_DOMAIN,
      {
        members: Object.keys(config.segments).filter((n) => !isChromeExempt(n)),
        library: {
          groups: LIBRARY_GROUPS.map((id) => ({
            id,
            label: GROUP_LABELS[id],
          })),
          entry: (option) => {
            const decl = config.segments[option]!;
            return {
              group: decl.group ?? OTHER_GROUP,
              ...(decl.description !== undefined && {
                description: decl.description,
              }),
            };
          },
        },
      },
    ],
  ]);
}

// One edit-mode chrome cell: a segment visible exactly while edit mode is on.
function chromeCell(
  name: string,
  template: string,
  artifacts: ChromeArtifacts,
): SegmentNode {
  // [LAW:one-type-per-behavior] An insertion point is drawn on no fill: its
  // `✚` is green TEXT on the terminal's own ground (`NO_FILL`), where a
  // placement's `✖` sits inside that placement's own cell.
  artifacts.segments[name] = { template, when: EDIT_MODE_GATE, bg: NO_FILL };
  return { kind: "segment", name };
}

// The `-` affordance (drawn `✖`) for one placement, addressed by its id: a
// literal `removeSegment` action, and the `{{ action }}` that clicks it. The
// action is named by its POSITION, as an insertion's is: an id is free text,
// and `ident` would collapse `git-2` and `git_2` onto one action. It is red
// TEXT on the cell's own ground, floored to stay legible on it, as the `✚`
// beside it is green.
function removeTerm(ctx: SpliceCtx, posIdent: string, id: string): string {
  const actionName = `${EDIT_NS}${ctx.presetIdent}.remove.${posIdent}`;
  ctx.artifacts.actions[actionName] = {
    persist: ctx.rootKey,
    removeSegment: id,
  };
  const remove = `readableOn (color "error") (bgOf) ${TEXT_MIN_CONTRAST}`;
  return `{{ fg (${remove}) (action "${actionName}" "${REMOVE_GLYPH}") }}`;
}

// An affordance drawn inside a placement's own cell — its `✖` as the segment
// node's `lead`, its `🔧` as its `trail` — so nothing sits between a placement
// and what acts on it. Neither is a segment, so no segment `when` hides it:
// each carries arrange mode's gate itself.
function inArrangeMode(term: string): string {
  return `{{ if ${disclosureTerm(EDIT_MODE_REF)} }}${term}{{ end }}`;
}

// ─── Configure mode (brandon-segment-settings-i4n.g64) ──────────────────────

// What configure mode shows whatever the author's `when` says: the label of
// the placement being configured, which its controls hang on, and every
// container holding it. A placement hidden right now — by the data, by an
// enclosing row's gate, or by the very setting just toggled — would otherwise
// take the controls that could change that with it. The label also names
// which placement they configure. Configuring is a level inside arranging,
// so it holds only while arranging does: a placement left configured when edit
// mode closed shows nothing. A fold over the configure refs a node holds: none
// leaves `when` exactly as it was.
function shownWhile(refs: readonly DisclosureRef[], when: string): string {
  return refs.reduce(
    (inner, ref) =>
      `{{ if and ${disclosureTerm(EDIT_MODE_REF)} ${disclosureTerm(ref)} }}true{{ else }}${inner}{{ end }}`,
    when,
  );
}

// The configure refs a spliced subtree holds: every label's disclosure over
// the configure key.
function configureRefsIn(nodes: readonly LayoutNode[]): DisclosureRef[] {
  return nodes.flatMap((node) =>
    [...walkNodes(node)].flatMap((n) =>
      n.kind === "segment" && n.opens?.ref.key === EDIT_CONFIGURE_KEY
        ? [n.opens.ref]
        : [],
    ),
  );
}

// [LAW:one-source-of-truth] THE session key an unsaved value of one
// placement's setting lives at: the preset (a placement's id is unique only in
// the tree one preset renders), the id, and the setting. A setting name is an
// identifier and a preset's ident holds no `.`, so the last segment is always
// the setting and the second the preset — the key names one value.
export function placementDraftKey(
  presetIdent: string,
  id: string,
  setting: string,
): string {
  return `${PLACEMENT_DRAFT_NS}${presetIdent}.${id}.${setting}`;
}

// What configure mode adds to one placement: the `🔧` that
// enters it, the controls it hangs below the placement while it is on, and the
// draft variables those controls write and the placement reads `.settings`
// through. The body is a disclosure over `edit.configure` at this placement's
// `<preset>:<id>` member, so its `✕` writes that key closed, configuring
// another placement closes it by overwriting the value it is open on, and
// leaving edit mode by any control closes it (`within` edit mode,
// src/config/disclosure-nest.ts).
interface ConfigureParts {
  readonly term: string;
  readonly ref: DisclosureRef;
  readonly body: ContainerNode;
  readonly drafts: Readonly<Record<string, DraftSlot>>;
}

function configureParts(
  ctx: SpliceCtx,
  posIdent: string,
  node: SegmentNode,
  decls: Readonly<Record<string, SettingDecl>>,
): ConfigureParts {
  const id = placementId(node);
  const prefix = `${EDIT_NS}${ctx.presetIdent}`;
  const member = configureMember(ctx.presetIdent, id);
  ctx.configured.push(member);
  const enter = `${prefix}.configure.${posIdent}`;
  // A shared `{{ menu }}` key's spelling: `ident`-normalized under `menus.`, so
  // it is a template path no other variable owns. Named by position, so the
  // placement configured there next would find a list left open; entering
  // configure folds it, and each visit starts with every list closed.
  // [LAW:single-enforcer] exception: closing configure folds this list too
  // (disclosure-nest.ts), but a layout edit releases configure on the
  // reloaded config, where the removed placement's member nests nothing.
  const listKey = sharedMenuStateKey(enter);
  const fold = `${enter}.fold`;
  ctx.artifacts.actions[fold] = { set: listKey, to: DISCLOSURE_CLOSED };
  ctx.artifacts.actions[enter] = {
    do: [`${enter}.open`, fold],
  };
  ctx.artifacts.actions[`${enter}.open`] = {
    set: EDIT_CONFIGURE_KEY,
    to: member,
  };
  const drafts: Record<string, DraftSlot> = {};
  const controls: LayoutNode[] = Object.entries(decls).map(([name, decl]) => {
    const key = placementDraftKey(ctx.presetIdent, id, name);
    // Named by position so it is a template field path (`.edit.draft.pp.d3.x`):
    // an id is free text, and a preset's ident may lead with a digit, which a
    // field name may not — hence its `p`. The key, not the name, is what a
    // session holds across reloads.
    const variable = `${PLACEMENT_DRAFT_NS}p${ctx.presetIdent}.d${posIdent}.${name}`;
    ctx.artifacts.variables[variable] = {
      kind: "state",
      key,
      default: settingSpelling(node.settings?.[name] ?? decl.default),
    };
    drafts[name] = { id, key, variable };
    const segName = `${prefix}.setting.${posIdent}.${name}`;
    // [LAW:one-type-per-behavior] The settings menu's generator; the lists of
    // one placement's pickers share one accordion.
    const control = settingControl(
      controlDeclOf(decl),
      key,
      variable,
      segName,
      listKey,
    );
    Object.assign(ctx.artifacts.actions, control.actions);
    Object.assign(ctx.artifacts.variables, control.variables);
    if (control.kind === "inline") {
      ctx.artifacts.segments[segName] = { template: control.template };
      return { kind: "segment", name: segName };
    }
    ctx.artifacts.segments[segName] = { template: control.template };
    const rows = control.list.rows.map((template, row): LayoutNode => {
      const listSeg = `${segName}.list.${row}`;
      ctx.artifacts.segments[listSeg] = { template };
      return { kind: "segment", name: listSeg };
    });
    return disclosureNode(
      segName,
      control.list.ref,
      { kind: "container", direction: "vertical", children: rows },
      "drop",
    );
  });
  return {
    term: `{{ action "${enter}" "${CONFIGURE_GLYPH}" }}`,
    ref: { variable: EDIT_CONFIGURE_KEY, key: EDIT_CONFIGURE_KEY, member },
    // One control per row, its list dropping below it when opened.
    body: { kind: "container", direction: "vertical", children: controls },
    drafts,
  };
}

// `ident` (every per-preset chrome name's `edit.<preset>.` prefix) emits no
// `:`, so no preset's chrome can land under this namespace.
const LABEL_NS = `${EDIT_NS}label:`;

// [LAW:one-source-of-truth] The segment a placed segment stands for in the
// layout's ARRANGEMENT (what `{{ layoutPreview }}` draws): a name label stands
// for the segment it names, since in edit mode it holds that segment's cell;
// every other edit-mode cell is an affordance over the arrangement, not part
// of it; anything else is itself.
export function arrangedSegment(name: string): string | undefined {
  if (name.startsWith(LABEL_NS)) {
    const label = name.slice(LABEL_NS.length);
    return label.slice(label.indexOf(":") + 1);
  }
  return name.startsWith(EDIT_NS) ? undefined : name;
}

// The name a placement wears in edit mode: its id, which is what tells two
// placements of one segment apart. Declared as `edit.label:<id>:<segment>` —
// an id holds no `:` (the loader refuses one), so `arrangedSegment` splits the
// segment back out exactly. The declaration says the same thing in every
// preset, so N presets holding one placement mint one; what differs per
// preset — the configure member it shows under — is on the node.
//
// The label holds its placement's cell in the names view, so it wears that
// placement's theme and effect: the definition's default theme on the
// declaration, the placement's own values and its unsaved picks on the node —
// the same draft slots the placement reads, so the two cannot show different
// ones.
function labelChrome(
  child: SegmentNode,
  decl: SegmentDecl,
  ctx: SpliceCtx,
  configure: ConfigureParts,
): SegmentNode {
  const id = placementId(child);
  const name = labelSegment(ctx, id, child, decl, id);
  // [LAW:one-source-of-truth] Every implied setting rides across — the theme
  // and the effect the placement wears, saved and unsaved — so a name moves as
  // its placement would.
  const settings = Object.fromEntries(
    IMPLIED_SETTINGS.flatMap((setting) => {
      const value = child.settings?.[setting];
      return value === undefined ? [] : [[setting, value]];
    }),
  );
  return {
    ...disclosureNode(
      name,
      configure.ref,
      configure.body,
      "drop",
      shownWhile([configure.ref], `{{ ${namesView(ctx.presetIdent)} }}`),
    ),
    ...(Object.keys(settings).length > 0 && { settings }),
    drafts: Object.fromEntries(
      IMPLIED_SETTINGS.map((setting) => [setting, configure.drafts[setting]!]),
    ),
  };
}

// [LAW:one-source-of-truth] THE declaration of a placement's names-view label,
// reading `text`, shared by the label that opens configure and the bare one an
// inserted cell wears. Returns the segment name it declared,
// `edit.label:<key>:<segment>`: `key` names one text, so two labels that read
// differently never share a declaration.
function labelSegment(
  ctx: SpliceCtx,
  key: string,
  child: SegmentNode,
  decl: SegmentDecl,
  text: string,
): string {
  const name = `${LABEL_NS}${key}:${child.name}`;
  ctx.artifacts.segments[name] = {
    template: `{{ "${escapeTemplateLiteral(text)}" }}`,
    ...(decl.palette !== undefined && { palette: decl.palette }),
  };
  return name;
}

// The unit an editable content cell gets: the leading `+` when it is the
// row's first content, its label (opening configure), the cell wearing `✖`
// and configure, and the `+` after it.
function editableUnit(
  child: SegmentNode,
  spliced: SegmentNode,
  first: boolean,
  ctx: SpliceCtx,
): LayoutNode[] {
  const id = placementId(child);
  const leading = first
    ? [insertTerm(ctx, String(ctx.posCounter.n++), id, "before")]
    : [];
  const afterPos = String(ctx.posCounter.n++);
  const after = insertTerm(ctx, afterPos, id, "after");
  // Every content segment has exactly one `after` insertion, so its
  // position names its removal and its configuration too.
  const remove = removeTerm(ctx, afterPos, id);
  // Every placement has settings — `theme` at least (settingsOf) — so
  // every placement configures. [LAW:no-defensive-null-guards] cross-ref
  // proved every placed segment is declared.
  const decl = ctx.segments[child.name]!;
  const configure = configureParts(ctx, afterPos, child, settingsOf(decl));
  // The buttons are drawn inside the cell of the placement they act on, in
  // whichever of the two views shows it, so nothing sits between them.
  const lead = inArrangeMode(remove);
  const trail = inArrangeMode(configure.term);
  return [
    ...leading.map((lead) =>
      chromeCell(lead.host, lead.template, ctx.artifacts),
    ),
    // Labelled by the placement's id: two placements of one segment are
    // told apart by it, and a bare placement's id is its segment's name.
    { ...labelChrome(child, decl, ctx, configure), lead, trail },
    {
      ...spliced,
      when: inNamesView(ctx.presetIdent, "false", child.when ?? "true"),
      lead,
      trail,
      drafts: configure.drafts,
    },
    chromeCell(after.host, after.template, ctx.artifacts),
  ];
}

// A config file as a label on the bar: its directory's name and its own.
// Every file a chain layers is named `.cc-candybar.*` or `config.*`, so the
// name alone can't tell a project's from a subdirectory's, and the directory
// beside it can; the full path would outrun the bar.
function fileLabel(file: string): string {
  return path.join(path.basename(path.dirname(file)), path.basename(file));
}

// The unit an inserted cell gets: the cell, and in the names view a label
// naming the file and entry that placed it. No `+`, `✖` or configure: the
// cell is an insert entry, which no click rewrites.
// [LAW:types-are-the-program] The click is not refused; it is never drawn.
function insertedUnit(
  child: SegmentNode,
  insertedBy: InsertedBy,
  spliced: SegmentNode,
  ctx: SpliceCtx,
): LayoutNode[] {
  const decl = ctx.segments[child.name]!;
  const id = placementId(child);
  const label: SegmentNode = {
    kind: "segment",
    // Keyed by the preset too: another preset may hold the same id as an
    // editable placement, whose label reads only the id. An id holds no
    // `/` and a preset ident no `:`, so the two names never meet.
    name: labelSegment(
      ctx,
      `${id}/${ctx.presetIdent}`,
      child,
      decl,
      `${id} · ${fileLabel(insertedBy.file)} ${insertedBy.entry}`,
    ),
    when: `{{ ${namesView(ctx.presetIdent)} }}`,
  };
  return [
    label,
    {
      ...spliced,
      when: inNamesView(ctx.presetIdent, "false", child.when ?? "true"),
    },
  ];
}

// The `+` affordance for one gap: an `insertSegmentFrom` action over this
// preset's addable domain, and the `{{ menu }}` over it for the cell `host` to
// carry (the menu's state key derives from its host segment's name). The menu's own disclosure (open state, page cursor, toggle action) is
// synthesized here by calling the SAME pure functions menu-synth.ts's
// file-parse-time pass calls — this pass runs too late to piggyback on that
// pass directly (it needs post-merge data menu-synth.ts's
// per-file timing does not have), so parity is achieved by sharing the
// functions, not by re-deriving the shape.
function insertTerm(
  ctx: SpliceCtx,
  posIdent: string,
  anchor: string,
  relation: "before" | "after",
): { readonly host: string; readonly template: string } {
  const { presetIdent, artifacts } = ctx;
  const applyName = `${EDIT_NS}${presetIdent}.insert.${posIdent}`;
  const chromeSegName = `${EDIT_NS}${presetIdent}.insertSeg.${posIdent}`;
  artifacts.actions[applyName] = {
    persist: ctx.rootKey,
    insertSegmentFrom: ADDABLE_DOMAIN,
    anchor,
    relation,
  };

  const member = menuMember(applyName);
  const stateKey = menuStateKey(chromeSegName, applyName, undefined);
  const pageKey = menuPageKey(stateKey);
  const identity = menuActionName(stateKey, member);
  // A `✚` is edit chrome, gated on edit mode rather than hung under it, so its
  // list says so: leaving edit mode closes it.
  artifacts.variables[stateKey] = {
    ...disclosureStateVar(stateKey, DISCLOSURE_CLOSED),
    within: [EDIT_MODE_REF],
  };
  artifacts.variables[pageKey] = { kind: "state", key: pageKey, default: "0" };
  artifacts.actions[identity] = disclosureCycleAction(stateKey, member);
  artifacts.actions[pageKey] = { set: pageKey, int: true };

  // The `+` IS the trigger — no appended arrow (candybar-settings-ui-aok.4).
  // Beside a `-` that means something else entirely, a ▸ read as part of the
  // affordance rather than as a disclosure hint, so the trigger names the ACTION
  // its click performs instead: `+` inserts here, `✕` closes what `+` opened —
  // the same glyph, and the same effect, as the body's own close cell.
  //
  // [LAW:no-silent-failure] It is deliberately NOT one static display. A preset
  // has N insertion points whose rendered rows are byte-identical, and their
  // dropped bodies are identical too. The open one does wear its band's state
  // colour (node-registry picks `styles.trigger` whenever a segment has drops,
  // authored bg or not), but colour alone is a hint the glyph should not
  // depend on: with one static display, "which one did I open" would rest on
  // a tint the terminal's colour depth may flatten. The `✕` names it.
  //
  // Closed, the `✚` is green TEXT on no fill at all (`NO_FILL`), so "add" reads
  // by colour beside the red ✖, floored to stay legible on the theme's own
  // background, which `bgOf` reads for a fill-less cell. Open, the `✕` keeps
  // the trigger's own chosen text: the trigger's ground is decided after the
  // body evaluates (by the drop this very menu makes), so `bgOf` cannot see
  // it and a floor measured against it would measure the wrong colour.
  const open = disclosureTerm({ variable: stateKey, key: stateKey, member });
  const add = `readableOn (color "success") (bgOf) ${TEXT_MIN_CONTRAST}`;
  return {
    host: chromeSegName,
    template:
      `{{ $m := menu "${applyName}" "${ADD_GLYPH}" "${DISCLOSURE_GLYPH_CLOSE}" }}` +
      `{{ if ${open} }}{{ $m }}{{ else }}{{ fg (${add}) $m }}{{ end }}`,
  };
}

// One splice's context, threaded unchanged through the recursion.
// `posCounter` is shared by reference so position identifiers stay unique
// across the WHOLE preset tree, not just one container.
interface SpliceCtx {
  readonly presetIdent: string;
  readonly rootKey: string;
  readonly segments: DslConfig["segments"];
  readonly artifacts: ChromeArtifacts;
  readonly posCounter: { n: number };
  // Every configure member the splice mints, collected for configuringVar.
  readonly configured: string[];
}

// [LAW:dataflow-not-control-flow] One recursive splice: every non-exempt
// segment child carries its `-` as its lead and `🔧` as its trail and is followed by one gap
// cell holding the `+` that inserts after it, and the first also leads with a
// `+` (so N consecutive segments read `+ [-seg1🔧] + [-seg2🔧] + [-seg3🔧] +` — N+1
// insert points, N remove points, N+1 chrome cells); a container child recurses; an exempt segment
// (a group toggle, a menu host, edit mode's own chrome) passes through
// untouched — but the disclosure BODY a segment hangs (a group's children,
// the settings rows) recurses like any container, so the cells inside an
// open group keep their `+`/`-` while the toggle that opens it has none.
function spliceContainer(node: ContainerNode, ctx: SpliceCtx): ContainerNode {
  const children: LayoutNode[] = [];
  // [LAW:one-source-of-truth] The leading `+`'s position is "before the
  // first CONTENT segment", not "before the first child": a row led by exempt
  // chrome — the settings door, where it defaults — would otherwise anchor on
  // a segment no layout op may move. The trailing insert point needs no such
  // rule: every content segment's gap cell carries its own `after`.
  // An inserted cell is not content a `+` may anchor on either: it is an
  // insert entry, which no click rewrites.
  const firstContent = node.children.findIndex(
    (child) =>
      child.kind === "segment" &&
      !isChromeExempt(child.name) &&
      child.insertedBy === undefined,
  );
  const splice = (body: ContainerNode): ContainerNode =>
    spliceContainer(body, ctx);
  for (const [i, child] of node.children.entries()) {
    if (child.kind === "container") {
      children.push(splice(child));
      continue;
    }
    const spliced = mapOpens(child, splice);
    if (isChromeExempt(child.name)) {
      children.push(spliced);
      continue;
    }
    // [LAW:dataflow-not-control-flow] Which unit a cell gets is read off the
    // cell: one a root holds is editable, one a layer's `insert` placed is
    // shown and labelled only.
    const cells =
      child.insertedBy === undefined
        ? editableUnit(child, spliced, i === firstContent, ctx)
        : insertedUnit(child, child.insertedBy, spliced, ctx);
    // [LAW:one-type-per-behavior] A content segment and its affordances are
    // ONE unit of the row: a horizontal container marked `unit`, whose
    // children share the one place in the row the content holds outside edit
    // mode, so the row places its content cells and nothing else. A cell's
    // place in its row is what its colour derives from (src/themes/decor.ts),
    // and every leaf of a row takes its own place through any plain container;
    // chrome given places took two of every three, so visible neighbours were
    // never consecutive and the row's shades collided
    // (brandon-theme-picker-bgw.8fp). Under a VERTICAL container the content
    // was a whole row (presetRoot stacks every root's rows vertically, so a
    // bare `"sidebar"` root and a `rows: { sys: "demo" }` row both arrive this
    // way): the unit becomes that row's one CELL, so the content keeps the
    // shade a one-cell row wears outside edit mode. The row carries no gate of
    // its own: the content's `when` stays on the content, so a hidden row still
    // shows its label and chrome in edit mode.
    const unit: LayoutNode = {
      kind: "container",
      direction: "horizontal",
      children: cells,
      unit: true,
    };
    children.push(
      node.direction === "vertical"
        ? { kind: "container", direction: "horizontal", children: [unit] }
        : unit,
    );
  }
  return {
    ...node,
    children,
    ...(node.when !== undefined && {
      when: shownWhile(
        configureRefsIn(children),
        inNamesView(ctx.presetIdent, "true", node.when),
      ),
    }),
  };
}

// brandon-layout-edit-2gc.5's other per-preset affordance: a `+`/`-` sibling
// that isn't about ONE gap but about the preset's authored root as a whole —
// synthesized the SAME way (one reset action targeting this preset's exact
// `persist` key, one segment hosting `{{ action }}`), UNCONDITIONALLY, with
// visibility carried entirely by CUSTOMIZED_BANNER_GATE
// [LAW:dataflow-not-control-flow]. It gets its own ROW (not a slot in the
// row-interleaved chrome spliceContainer builds) because it is not bound to any
// one segment gap — it is a fact about the whole tree — visible or not by a
// `when` that is every other synthesized affordance's edit-mode gate narrowed
// by the one extra fact this affordance depends on.
//
// candybar-settings-ui-aok.6 hangs edit mode's `(?)` off the same content. Its
// body hangs on the trigger (`SegmentNode.opens`) and drops below whichever row
// the trigger rides, so this function places ONE cell; see withTrailingCell.
function wrapWithPresetRows(
  splicedRoot: LayoutNode,
  presetIdent: string,
  rootKey: string,
  artifacts: ChromeArtifacts,
  lead: readonly LayoutNode[],
  live: LayoutNode,
  tail: LayoutNode,
): LayoutNode {
  const actionName = `${EDIT_NS}${presetIdent}.resetLayout`;
  const chromeSegName = `${EDIT_NS}${presetIdent}.customized`;
  // [LAW:no-silent-failure] `reset` deletes the root the file authors at
  // `rootKey`'s path (candybar-config-dqe), restoring the bundled preset's
  // own tree — or, for a preset that stages the config root, the bundled
  // root — on the next reload. `rootKey` is gated the SAME way every other
  // `presets.<name>.root` target is (deriveConfigActionValidators), and is
  // ALWAYS a registered key — config-validators.ts's presetRootContributions
  // registers it
  // for every declared preset UNCONDITIONALLY, specifically so a preset
  // edited down to zero non-exempt segments (no removeTerm/insertTerm
  // persist actions left to register it) doesn't orphan this exact click.
  artifacts.actions[actionName] = { reset: rootKey };
  artifacts.segments[chromeSegName] = {
    template: `{{ action "${actionName}" "↺ reset layout" }}`,
    when: CUSTOMIZED_BANNER_GATE,
  };
  return {
    kind: "container",
    direction: "vertical",
    children: [
      // The ways out lead the top row, top left, where they are found without
      // reopening the menu edit mode was entered from: keep or discard what
      // was changed, restore the bundled layout, and the view toggle.
      {
        kind: "container",
        direction: "horizontal",
        children: [...lead, { kind: "segment", name: chromeSegName }, live],
      },
      // The `(?)`'s body drops BELOW the row the trigger rides while the
      // disclosure is open, like every other disclosure body in this codebase.
      withTrailingCell(splicedRoot, tail),
    ],
  };
}

// [LAW:one-source-of-truth] The `(?)` is a CELL, and its contract is that the
// caller joins it to a row it ALREADY HAS. Edit mode's rows are the ones
// spliceContainer just built, so the trigger joins the last of them. Two constraints pin that
// placement and nothing else satisfies both:
//
//  - Closed help must cost no LINE. A trigger given its own vertical slot is a
//    permanent row for the whole time edit mode is on, since a trigger's `when`
//    is its host surface's, never its own open state (a trigger you must open in
//    order to see could never be opened).
//  - Closed help must not MOVE the content. A cell trailing the last row sits
//    after every existing leaf, so no authored node's address — the position
//    its colour derives from — changes; the reset-banner row sits above the
//    content and is ruled out on that ground.
//
// A THIRD requirement decides how far the descent may go, and it outranks the
// other two: the trigger must be visible exactly when EDIT MODE is, since a
// trigger you must already have opened something else to reach is not a trigger.
// A container's `when` reaches every descendant, so descending into a
// `when`-bearing container would silently make its gate the trigger's gate.
// Pairing beside a gated SEGMENT is a different act and stays allowed:
// `{h: [gatedSeg, cell]}` puts the cell beside the gate rather than under it.
// A disclosure BODY is never descended into either, by shape: it hangs on its
// trigger segment (`SegmentNode.opens`) rather than sitting in the children
// list, so a preset root ending in a `kind: "group"` — ordinary authoring the
// A-grammar endorses — pairs the `(?)` beside the group's toggle, never inside
// a body most groups default closed.
//
// For a root whose last row is gated the three requirements are jointly
// unsatisfiable, so the priority is stated rather than left to whichever branch
// the recursion happens to reach: visible (always) > no move (always, since
// appending is still after every existing leaf) > no extra line (surrendered
// here, in exactly the configs where riding a row was never possible).
//
// [LAW:dataflow-not-control-flow] Total over the node shapes with no guard: a
// segment is a row of one that cannot hold a second cell, so it pairs into one;
// a vertical container's rows are its children, so it descends into the last one
// it may; anything else appends. An empty container has no last child and
// appends, which is the same answer.
function withTrailingCell(node: LayoutNode, cell: LayoutNode): LayoutNode {
  if (node.kind === "segment") {
    return {
      kind: "container",
      direction: "horizontal",
      children: [node, cell],
    };
  }
  const last = node.children.at(-1);
  if (
    node.direction === "vertical" &&
    last !== undefined &&
    (last.kind === "segment" || last.when === undefined)
  ) {
    return {
      ...node,
      children: [...node.children.slice(0, -1), withTrailingCell(last, cell)],
    };
  }
  return { ...node, children: [...node.children, cell] };
}

// One preset's chrome-spliced root. presetRoot always yields a container —
// the merged rows stacked vertically — so a bare-segment fragment (the
// A-grammar's `{ seg, when }` shorthand is a legal root) arrives already
// wrapped as its one row, its own `when` lifted to the root, and a lone
// segment gets a `+` on each side like any other.
function spliceEditChromeForPreset(
  config: DslConfig,
  presetName: string,
  artifacts: ChromeArtifacts,
  lead: readonly LayoutNode[],
  live: LayoutNode,
  tail: LayoutNode,
): LayoutNode {
  const { node } = presetRoot(config, presetName);
  const ctx: SpliceCtx = {
    presetIdent: ident(presetName),
    rootKey: presetRootKey(presetName),
    segments: config.segments,
    artifacts,
    posCounter: { n: 0 },
    configured: [],
  };
  const spliced = spliceContainer(node, ctx);
  artifacts.variables[configuringVar(ctx.presetIdent)] = configuringDecl(
    ctx.configured,
  );
  return wrapWithPresetRows(
    spliced,
    ctx.presetIdent,
    ctx.rootKey,
    artifacts,
    lead,
    live,
    tail,
  );
}

// [LAW:single-enforcer] THE synthesis entry point, called once from
// validateRenderable after cross-ref/cycle checks pass. Every declared preset
// (the floor "default" included — presetNames/presetByName/presetRoot
// already treat it uniformly) gets an explicit `presets[name].root` carrying
// its spliced tree; `config.root` itself is left untouched (presetRoot falls
// back to it only when a preset declares no root of its own, and every name
// now does). The synthesized variables/actions/segments merge additively —
// nothing here can collide with user data, since every name it mints lives
// under the `edit.`/`menus.` namespaces `synthesizeEditModeToggle` and
// `checkMenuDecls` already reserve unconditionally at parse time.
//
// Unconditional: the settings menu, synthesized into every config just before
// this pass, ensures `edit.toggle` and puts `✎ arrange` in its body, so every bar
// can reach edit mode (brandon-settings-menu-d6f).
export function synthesizeEditChrome(config: DslConfig): DslConfig {
  const artifacts: ChromeArtifacts = {
    variables: {},
    actions: {},
    segments: {},
  };
  // [LAW:one-source-of-truth] Edit mode's `(?)` is minted ONCE and merely
  // REFERENCED from every preset root — the same move the settings menu makes
  // with its anchor, and for the same reason: one disclosure means one open
  // state, so switching presets cannot land you beside a second `(?)` that
  // disagrees about whether help is showing. The text is identical for every
  // preset because what `+` and `-` do is a fact about edit mode, not about a
  // layout.
  const help = declareHelp(
    `${EDIT_NS}help`,
    EDIT_MODE_HELP,
    [EDIT_MODE_REF],
    artifacts,
  );
  // The view toggle rides the same trailing cell as the `(?)`, minted once for
  // the same reason: one key, so switching presets keeps the view you chose.
  artifacts.variables[EDIT_LIVE_KEY] = disclosureStateVar(
    EDIT_LIVE_KEY,
    DISCLOSURE_CLOSED,
  );
  artifacts.actions[EDIT_LIVE_KEY] = disclosureCycleAction(
    EDIT_LIVE_KEY,
    EDIT_LIVE_REF.member,
  );
  artifacts.segments[EDIT_LIVE_KEY] = {
    template: disclosureTrigger(EDIT_LIVE_KEY, ...EDIT_LIVE_DISPLAY),
    when: EDIT_MODE_GATE,
  };
  // The view toggle leads the edit row with the other edit-mode controls; the
  // `(?)` alone trails the bar's last row.
  const live: LayoutNode = { kind: "segment", name: EDIT_LIVE_KEY };
  const tail: LayoutNode = help;
  // Leaving edit mode, minted once like the `(?)`: the same toggle the menu's
  // `✎ arrange` fires, and what leaving closes is the nest's
  // (src/config/disclosure-nest.ts). `✓` also saves; the menu's `✎ done` does
  // not, and leaves anything unsaved to the `💾 save` beside it.
  artifacts.variables[EDIT_CHANGES_VAR] = {
    kind: "input",
    path: "history.sinceEdit",
    type: "number",
    default: 0,
  };
  // [LAW:one-source-of-truth] Saving is the settings menu's own `💾 save`
  // action, so the two cannot disagree about what saving writes.
  artifacts.actions[EDIT_DONE_SEG] = {
    do: [SAVE_SEG, EDIT_TOGGLE_ACTION],
  };
  artifacts.segments[EDIT_DONE_SEG] = {
    template:
      `{{ if ${TO_KEEP} }}{{ action "${EDIT_DONE_SEG}" "✓ save" }}` +
      `{{ else }}{{ action "${EDIT_DONE_SEG}" "✓ done" }}{{ end }}`,
    when: EDIT_MODE_GATE,
  };
  // [LAW:one-source-of-truth] Cancel is the rewind and then the same toggle
  // `✓` fires, as one click: the rewind is the face, the toggle rides along
  // (`do`), so leaving edit mode closes exactly what it closes everywhere.
  artifacts.actions[EDIT_REWIND_ACTION] = { rewind: true };
  artifacts.actions[EDIT_CANCEL_SEG] = {
    do: [EDIT_REWIND_ACTION, EDIT_TOGGLE_ACTION],
  };
  // [LAW:dataflow-not-control-flow] Hidden by data, not by a branch: with
  // nothing changed there is nothing to discard.
  artifacts.segments[EDIT_CANCEL_SEG] = {
    template: `{{ action "${EDIT_CANCEL_SEG}" "↩ cancel" }}`,
    when: `{{ and ${disclosureTerm(EDIT_MODE_REF)} ${CHANGED} }}`,
  };
  const lead: LayoutNode[] = [
    { kind: "segment", name: EDIT_DONE_SEG },
    { kind: "segment", name: EDIT_CANCEL_SEG },
  ];
  const presets: Record<string, PresetDecl> = { ...config.presets };
  const roots: LayoutNode[] = [];
  for (const name of presetNames(config.presets)) {
    const root = spliceEditChromeForPreset(
      config,
      name,
      artifacts,
      lead,
      live,
      tail,
    );
    roots.push(root);
    presets[name] = { ...presetByName(config.presets, name), root };
  }
  // [LAW:no-silent-failure] What the chrome reads and the config does not
  // declare (the banner's `.preset.customized`, the session.id every click
  // carries), merged UNDER the config so a user's own declaration wins.
  const ensured = synthesisInputs(artifacts, roots, config);
  return {
    ...config,
    variables: {
      ...ensured,
      ...config.variables,
      ...artifacts.variables,
    },
    actions: { ...config.actions, ...artifacts.actions },
    segments: { ...config.segments, ...artifacts.segments },
    presets,
  };
}
