/**
 * FlexStrip — wrap-to-width horizontal layout for `StyledRenderable` items.
 *
 * Pack as many items as fit on a line, then break and continue. Each line is
 * an independent sub-strip: optional `Joiner` end-caps fire at every line
 * boundary (not just the strip's first/last position), so a line break looks
 * the same as an endpoint to the joiner. Composes with the Strip + Joiner
 * primitive in `core/strip` — same `Joiner` protocol, no new join semantics.
 *
 * [LAW:dataflow-not-control-flow] The pack walk is the same shape every
 * render: measure each item, render every joiner form (start-cap, end-cap,
 * mid-join) up-front, then sweep items into lines. Line breaks are decided by
 * width data, not by control-flow special cases.
 *
 * [LAW:one-source-of-truth] The Strip primitive owns the join protocol;
 * FlexStrip reuses it verbatim. There is no second concept of "join."
 */
import { Segment } from "../core/segment.js";
import { render } from "../core/protocol.js";
import { drawItem, drawJoin } from "../core/strip.js";
function renderToBlock(r, options) {
    const segments = [...render(r, options)];
    let width = 0;
    for (const s of segments)
        width += s.cellLength;
    return { segments, width };
}
const EMPTY_BLOCK = { segments: [], width: 0 };
const PAD_LEFT_BY_ALIGN = {
    left: () => 0,
    justify: () => 0,
    center: (spare) => Math.floor(spare / 2),
    right: (spare) => spare,
};
function computePadLeft(align, spare) {
    return PAD_LEFT_BY_ALIGN[align](spare);
}
// Return per-slot fill widths (length = itemCount - 1, possibly empty).
// Non-justify cases produce all zeros — the emit loop runs the same way.
function computeSlotFills(align, isFinalLine, spare, itemCount) {
    const slots = Math.max(0, itemCount - 1);
    const distribute = align === "justify" && !isFinalLine && slots > 0 && spare > 0;
    const totalFill = distribute ? spare : 0;
    const base = slots > 0 ? Math.floor(totalFill / slots) : 0;
    const extra = totalFill - base * slots;
    return Array.from({ length: slots }, (_, k) => base + (k < extra ? 1 : 0));
}
export class FlexStrip {
    items;
    joiner;
    gap;
    align;
    constructor(items, options) {
        this.items = items;
        this.joiner = options?.joiner;
        this.gap = options?.gap ?? 0;
        this.align = options?.align ?? "left";
    }
    *render(options) {
        const items = this.items;
        if (items.length === 0)
            return;
        const maxWidth = Math.max(1, options.maxWidth);
        const gap = this.gap;
        const joiner = this.joiner;
        // Pre-render every item and every joiner form we might need. Doing this
        // up-front turns packing into a pure data computation over widths.
        const itemBlocks = items.map((it) => renderToBlock(drawItem(it), options));
        const startCap = (i) => joiner ? renderToBlock(drawJoin(joiner, null, items[i], { index: i }), options) : EMPTY_BLOCK;
        const endCap = (i) => joiner ? renderToBlock(drawJoin(joiner, items[i], null, { index: i + 1 }), options) : EMPTY_BLOCK;
        const midJoin = (i, j) => joiner ? renderToBlock(drawJoin(joiner, items[i], items[j], { index: j }), options) : EMPTY_BLOCK;
        const lines = [];
        let line = null;
        const gapBlock = gap > 0
            ? { segments: [new Segment(" ".repeat(gap))], width: gap }
            : EMPTY_BLOCK;
        for (let i = 0; i < items.length; i++) {
            const item = itemBlocks[i];
            if (line === null) {
                const sc = startCap(i);
                const ec = endCap(i);
                const blocks = sc.width > 0 ? [sc, item] : [item];
                const itemBlockIndices = [blocks.length - 1];
                line = { blocks, width: sc.width + item.width, lastIndex: i, itemBlockIndices };
                // Tentatively reserve space for the line's eventual end-cap by
                // tracking it separately below — `line.width` is the open width
                // (without end-cap). We test fit using width + endCap on each step.
                // Always start a new line with at least the first item (overflow ok
                // per ticket: graceful fallback when an item is wider than terminal).
                // Stash end-cap for the close step.
                line.endCap = ec;
                continue;
            }
            const prev = line.lastIndex;
            const mid = midJoin(prev, i);
            const newEndCap = endCap(i);
            const addCost = (gap > 0 ? gap : 0) + mid.width + (gap > 0 ? gap : 0) + item.width;
            const closedWidthIfAdded = line.width + addCost + newEndCap.width;
            if (closedWidthIfAdded <= maxWidth) {
                if (gap > 0)
                    line.blocks.push(gapBlock);
                if (mid.width > 0)
                    line.blocks.push(mid);
                if (gap > 0)
                    line.blocks.push(gapBlock);
                line.blocks.push(item);
                line.itemBlockIndices.push(line.blocks.length - 1);
                line.width += addCost;
                line.lastIndex = i;
                line.endCap = newEndCap;
            }
            else {
                // Close current line and start a new one with this item.
                const closing = line.endCap;
                if (closing.width > 0)
                    line.blocks.push(closing);
                line.width += closing.width;
                lines.push(line);
                const sc = startCap(i);
                const ec = endCap(i);
                const blocks = sc.width > 0 ? [sc, item] : [item];
                const itemBlockIndices = [blocks.length - 1];
                line = { blocks, width: sc.width + item.width, lastIndex: i, itemBlockIndices };
                line.endCap = ec;
            }
        }
        // Close final line. `line` is non-null here: the loop runs at least once
        // (items.length > 0 was handled above).
        const finalLine = line;
        {
            const closing = finalLine.endCap;
            if (closing.width > 0)
                finalLine.blocks.push(closing);
            finalLine.width += closing.width;
            lines.push(finalLine);
        }
        // [LAW:dataflow-not-control-flow] Single emission path for every line:
        // emit pad, walk every block, optionally emit a per-slot fill before each
        // non-first item. Variability lives in two precomputed value sequences
        // (`padLeft` and `slotFills`); the emit loop has no per-mode branch.
        //
        // - `padLeft` pushes the line right by 0 (left/justify), spare/2 (center),
        //   or full spare (right). Justify-on-final-line follows the left rule.
        // - `slotFills[k]` is the cells of fill emitted before the (k+1)-th item.
        //   Always 0 unless align=justify on a non-final line with ≥2 items.
        //
        // Putting the variability in data means the emit loop is the same shape
        // every render, and "what happens between two items" can never accidentally
        // become "what happens between joiner halves" — the data decides.
        const align = this.align;
        for (let li = 0; li < lines.length; li++) {
            const ln = lines[li];
            const isLast = li === lines.length - 1;
            const spare = Math.max(0, maxWidth - ln.width);
            const padLeft = computePadLeft(align, spare);
            const slotFills = computeSlotFills(align, isLast, spare, ln.itemBlockIndices.length);
            const itemRankOf = new Map();
            ln.itemBlockIndices.forEach((blockIdx, rank) => itemRankOf.set(blockIdx, rank));
            if (padLeft > 0)
                yield new Segment(" ".repeat(padLeft));
            for (let bi = 0; bi < ln.blocks.length; bi++) {
                const rank = itemRankOf.get(bi);
                if (rank !== undefined && rank > 0) {
                    const fill = slotFills[rank - 1];
                    if (fill > 0)
                        yield new Segment(" ".repeat(fill));
                }
                yield* ln.blocks[bi].segments;
            }
            yield Segment.line();
        }
    }
    measure(options) {
        const items = this.items;
        if (items.length === 0)
            return { minimum: 0, maximum: 0 };
        let minimum = 0;
        let maximum = 0;
        for (let i = 0; i < items.length; i++) {
            const itemWidth = renderToBlock(items[i], options).width;
            const sc = this.joiner
                ? renderToBlock(drawJoin(this.joiner, null, items[i], { index: i }), options).width
                : 0;
            const ec = this.joiner
                ? renderToBlock(drawJoin(this.joiner, items[i], null, { index: i + 1 }), options).width
                : 0;
            minimum = Math.max(minimum, itemWidth + sc + ec);
            maximum += itemWidth;
            if (i > 0) {
                maximum += this.gap * 2;
                if (this.joiner) {
                    maximum += renderToBlock(drawJoin(this.joiner, items[i - 1], items[i], { index: i }), options).width;
                }
            }
        }
        if (this.joiner) {
            maximum += renderToBlock(drawJoin(this.joiner, null, items[0], { index: 0 }), options).width;
            maximum += renderToBlock(drawJoin(this.joiner, items[items.length - 1], null, { index: items.length }), options).width;
        }
        return { minimum, maximum };
    }
}
