// Which tmux panes someone can see (candybar-animation-wbxz.jmm): a subscribed
// session's bar is drawn at the moving rate only while its pane is on a screen.
// Brandon: "Assume 2 dozen live sessions needing active rendering, although if
// we can find some way of not rendering terminals that aren't visible that
// would be great." The daemon draws every frame on one thread, so two dozen
// sessions at thirty frames a second is its whole budget; most of those panes
// are in windows nobody is looking at.
//
// What a session's terminal is comes from its own statusline client (the
// `tmux` hint: socket and pane, src/tmux-hint.ts); whether that pane is shown
// comes from its tmux server, asked once a second per server.

import { inspect } from "node:util";
import type { TmuxHint } from "../tmux-hint.js";
import type { TmuxRun } from "../proc/tmux.js";

// One line per pane: its id, its session's id, how many clients that session
// has attached, and whether its window is the session's current one, zoomed,
// and itself the active pane.
export const LIST_PANES_FORMAT =
  "#{pane_id} #{session_id} #{session_attached} #{window_active} #{window_zoomed_flag} #{pane_active}";

// One line per client: the id of the session it is attached to, whether it is
// a control-mode client (iTerm2's `tmux -CC`), and its current pane — the
// active pane of its session's current window, the pane its status line is
// expanded for (measured, tmux 3.6a).
export const LIST_CLIENTS_FORMAT =
  "#{session_id} #{client_control_mode} #{pane_id}";

// The sessions a control-mode client is attached to. Such a client draws each
// of the session's windows as a native window of its own, any number of which
// can be on screen at once.
export function controlledSessions(listClients: string): ReadonlySet<string> {
  const controlled = new Set<string>();
  for (const line of listClients.split("\n")) {
    const [session, control] = line.trim().split(" ");
    if (session !== undefined && control === "1") controlled.add(session);
  }
  return controlled;
}

// The panes a client is showing: of a session at least one client is attached
// to, in a window that is its session's current one — or any of its windows,
// when a control-mode client draws them all — and, when that window is zoomed,
// only its active pane.
export function shownPanes(
  listPanes: string,
  controlled: ReadonlySet<string>,
): ReadonlySet<string> {
  const shown = new Set<string>();
  for (const line of listPanes.split("\n")) {
    const [pane, session, attached, current, zoomed, active] = line
      .trim()
      .split(" ");
    if (pane === undefined || pane === "" || session === undefined) continue;
    if (
      Number(attached) > 0 &&
      (current === "1" || controlled.has(session)) &&
      (zoomed !== "1" || active === "1")
    )
      shown.add(pane);
  }
  return shown;
}

// What a tmux server's status lines show: the session each of its panes is in,
// and for each session a client draws a status line for, the pane that status
// line is expanded for. A control-mode client draws no tmux status line.
export interface StatusLines {
  readonly sessionOf: ReadonlyMap<string, string>;
  readonly shownBy: ReadonlyMap<string, string>;
}

// [LAW:effects-at-boundaries] Pure over the same two answers `shownPanes`
// reads, in LIST_PANES_FORMAT and LIST_CLIENTS_FORMAT.
export function statusLinesOf(
  listPanes: string,
  listClients: string,
): StatusLines {
  const sessionOf = new Map<string, string>();
  for (const line of listPanes.split("\n")) {
    const [pane, session] = line.trim().split(" ");
    if (pane !== undefined && pane !== "" && session !== undefined)
      sessionOf.set(pane, session);
  }
  const shownBy = new Map<string, string>();
  for (const line of listClients.split("\n")) {
    const [session, control, pane] = line.trim().split(" ");
    if (session !== undefined && control === "0" && pane !== undefined)
      shownBy.set(session, pane);
  }
  return { sessionOf, shownBy };
}

// [LAW:types-are-the-program] What one tmux server last said: the panes it
// shows and what its status lines show, or why it could not be asked. A server
// that could not be asked shows every pane, so a failed query costs frames,
// never a frozen bar.
type ServerView =
  | {
      readonly kind: "asked";
      readonly shown: ReadonlySet<string>;
      readonly status: StatusLines;
    }
  | { readonly kind: "unasked"; readonly reason: string };

export interface VisibilityDeps {
  // `tmux list-panes -a` and `tmux list-clients` of the server at `socket`,
  // in LIST_PANES_FORMAT and LIST_CLIENTS_FORMAT.
  listPanes(socket: string): Promise<TmuxRun>;
  listClients(socket: string): Promise<TmuxRun>;
  // The servers to ask, read as each refresh of the loop starts.
  sockets(): ReadonlySet<string>;
  // Called after a refresh in which any server's shown panes changed, or
  // whether it could be asked, with those servers' sockets.
  onChange(sockets: ReadonlySet<string>): void;
  // Called on every refresh with each server that answered, and what its
  // status lines show.
  onAnswer(socket: string, status: StatusLines): void;
  // From the start of one refresh of the loop to the next.
  intervalMs: number;
  log(level: "info" | "warn" | "error", line: string): void;
}

// [LAW:no-ambient-temporal-coupling] The loop, as state: not running; a
// refresh in flight, and whether another follows it; or the next refresh due
// at a timer. One refresh at a time, so a server slower than the interval is
// never asked twice at once, nor answered out of order.
type Loop =
  | { readonly kind: "idle" }
  | { kind: "asking"; following: boolean }
  | { readonly kind: "due"; readonly timer: ReturnType<typeof setTimeout> };

/**
 * [LAW:no-shared-mutable-globals] Every tmux server's last answer, by socket:
 * one owner, written only by `refresh`, held only while the loop runs.
 */
export class PaneVisibility {
  private readonly servers = new Map<string, ServerView>();
  private loop: Loop = { kind: "idle" };

  constructor(private readonly deps: VisibilityDeps) {}

  // Asks the servers at once, then once per interval until the returned stop.
  // Stopped, it keeps no timer and forgets every server's answer.
  follow(): () => void {
    switch (this.loop.kind) {
      case "idle":
        this.deps.log("info", "visibility following");
        this.ask();
        break;
      case "asking":
        this.loop.following = true;
        break;
      case "due":
        break;
    }
    return () => this.stop();
  }

  private stop(): void {
    switch (this.loop.kind) {
      case "due":
        clearTimeout(this.loop.timer);
        this.end();
        return;
      case "asking":
        // The refresh in flight ends the loop when it answers.
        this.loop.following = false;
        return;
      case "idle":
        return;
    }
  }

  private ask(): void {
    const loop: Loop = { kind: "asking", following: true };
    this.loop = loop;
    // [LAW:no-ambient-temporal-coupling] Reading which servers to ask is part
    // of the refresh: a throw from it takes the same catch, and the loop goes
    // on rather than staying "asking" with nothing in flight.
    void Promise.resolve()
      .then(() => this.refresh(this.deps.sockets()))
      .catch((err: unknown) =>
        this.deps.log("error", `visibility refresh threw: ${inspect(err)}`),
      )
      .then(() => {
        if (loop.following) {
          this.loop = {
            kind: "due",
            timer: setTimeout(() => this.ask(), this.deps.intervalMs).unref(),
          };
          return;
        }
        this.end();
      });
  }

  // [LAW:nothing-unseen] The loop's end, said once, with the answers it drops.
  private end(): void {
    this.deps.log("info", `visibility stopped forgot=${this.servers.size}`);
    this.loop = { kind: "idle" };
    this.servers.clear();
  }

  // Whether a session whose client reported `tmux` is on a screen. A session
  // outside tmux, from a client too old to say, or on a server not yet asked,
  // cannot be told apart from one that is, so it is.
  shown(tmux: TmuxHint | null | undefined): boolean {
    if (tmux === null || tmux === undefined) return true;
    const view = this.servers.get(tmux.socket);
    return view?.kind !== "asked" || view.shown.has(tmux.pane);
  }

  // Asks each of `sockets` which panes it shows, and forgets every server not
  // among them. One query per server, all at once.
  private async refresh(sockets: ReadonlySet<string>): Promise<void> {
    for (const socket of this.servers.keys())
      if (!sockets.has(socket)) this.servers.delete(socket);
    const answers = await Promise.all(
      [...sockets].map(async (socket) => {
        const [panes, clients] = await Promise.all([
          this.deps.listPanes(socket),
          this.deps.listClients(socket),
        ]);
        const view: ServerView =
          panes.kind !== "ok"
            ? { kind: "unasked", reason: panes.reason }
            : clients.kind !== "ok"
              ? { kind: "unasked", reason: clients.reason }
              : {
                  kind: "asked",
                  shown: shownPanes(
                    panes.stdout,
                    controlledSessions(clients.stdout),
                  ),
                  status: statusLinesOf(panes.stdout, clients.stdout),
                };
        return [socket, view] as const;
      }),
    );
    const changed = new Set<string>();
    for (const [socket, view] of answers) {
      const before = this.servers.get(socket);
      this.servers.set(socket, view);
      if (sameView(before, view)) continue;
      changed.add(socket);
      // [LAW:no-silent-failure] Each change of what a server shows, or of
      // whether it can be asked, is logged once — not each second.
      this.deps.log(
        view.kind === "asked" ? "info" : "warn",
        view.kind === "asked"
          ? `visibility socket=${JSON.stringify(socket)} shown=${[...view.shown].join(",") || "-"}`
          : `visibility socket=${JSON.stringify(socket)} unasked: ${view.reason} — its panes count as shown`,
      );
    }
    for (const [socket, view] of answers)
      if (view.kind === "asked") this.deps.onAnswer(socket, view.status);
    if (changed.size > 0) this.deps.onChange(changed);
  }
}

function sameView(a: ServerView | undefined, b: ServerView): boolean {
  if (a === undefined || a.kind !== b.kind) return false;
  if (a.kind === "unasked" || b.kind === "unasked") return true;
  return (
    a.shown.size === b.shown.size && [...a.shown].every((p) => b.shown.has(p))
  );
}
